/**
 *
 **/

Ext._define('rh.legalprocess.LegalProcessManage', {
    extend: 'toolkit.widget.TabPanel',

    getLegalProcessGrid: function() {
        if(!this._processgrid){
            this._processgrid = Ext._create('rh.legalprocess.LegalProcessGrid', {
                region: 'center',
                suspensionsGrid: this.getSuspensionsGrid(),
            });
        }

        this._processgrid.getSelectionModel().on({
                scope: this,
                rowselect: function(sm, index, data){
                    this.process(data.get('pk'));
                },
                rowdeselect: function(){ 
                    this.process(null);
                },
        });

        return this._processgrid;
    },

    getSuspensionsGrid: function(){
        if(!this._suspensionsgrid){
            this._suspensionsgrid = Ext._create('rh.legalprocess.ProcessSuspensionGrid', {
                region: 'south',
                height: 350,
                split: true,
                gridAutoLoad: false
            });

        }

        return this._suspensionsgrid;
    },

    process: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true)

        if(value !== undefined){
            this._process = value;

            if(dispatch) this.observeSuspensions();
        }
        else
            return this._process;
    },

    observeSuspensions: function(){
        if(this.process()){
            this.getSuspensionsGrid().enable();
            this.getSuspensionsGrid().setParam('process', this.process());
            this.getSuspensionsGrid().setFilterProperty('process_id', this.process(), 100);
        }
        else{
            this.getSuspensionsGrid().disable();
            this.getSuspensionsGrid().getStore().removeAll();
            this.getSuspensionsGrid().setFilterProperty('process_id', 0, 100, false);
        }
    },

    constructor: function(cfg) {
        cfg = cfg ? cfg : {};

        Ext.applyIf(
            cfg,
            {
               title: 'Processos - eSocial'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items:[
                    this.getLegalProcessGrid(),
                    this.getSuspensionsGrid()
                ]
            }
        );

        rh.legalprocess.LegalProcessManage.superclass.constructor.call(this, cfg);
        this.observeSuspensions();

    }
});
